[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Provider=Join-Path $PSScriptRoot '..\..\controller\providers\HpSystemInfoHsaManualDemandStart.ps1'
$TaskName='Lacksan-EXP-065-Validation'
$Pointer=Join-Path $EvidenceRoot 'active.json'
function Write-Json($Path,$Value){$Value|ConvertTo-Json -Depth 16|Set-Content -LiteralPath $Path -Encoding UTF8}
function Read-Json($Path){Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json}
function Median($Values){$a=@($Values|Where-Object{$null-ne$_}|ForEach-Object{[double]$_}|Sort-Object);if(!$a.Count){return $null};$m=[math]::Floor($a.Count/2);if($a.Count%2){$a[$m]}else{($a[$m-1]+$a[$m])/2}}
function Mad($Values){$m=Median $Values;if($null-eq$m){return $null};Median @($Values|ForEach-Object{[math]::Abs([double]$_-$m)})}
function BootId{(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o')}
function Require-Admin{$p=[Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent();if(!$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required.'}}
function Resolve-Run{if($RunDirectory){return (Resolve-Path $RunDirectory).Path};if(!(Test-Path $Pointer)){throw 'No active EXP-065 run.'};(Resolve-Path (Read-Json $Pointer).runDirectory).Path}
function Paths($d){[pscustomobject]@{Harness=Join-Path $d 'harness-state.json';State=Join-Path $d 'provider-state.json';Log=Join-Path $d 'provider.jsonl';Summary=Join-Path $d 'summary.json'}}
function Provider($Action,$d){$p=Paths $d;& $Provider -Action $Action -StatePath $p.State -LogPath $p.Log}
function Protected{[ordered]@{Defender=@(Get-Service WinDefend -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType);Firewall=@(Get-Service mpssvc -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType);WindowsUpdate=@(Get-Service wuauserv -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType);Rdp=@(Get-Service TermService -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType);Tailscale=@(Get-Service Tailscale -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType);Omnissa=@(Get-Process vmware-view,horizon-client -ErrorAction SilentlyContinue|Select-Object ProcessName,Id);WindowsApp=@(Get-Process msrdc -ErrorAction SilentlyContinue|Select-Object ProcessName,Id)}}
function Collect($Phase,$Ordinal,$d){$boot=BootId;$existing=@(Get-ChildItem $d -Filter "run-$Phase-*.json" -ErrorAction SilentlyContinue|ForEach-Object{Read-Json $_.FullName});if($existing.bootId -contains $boot){throw 'Duplicate boot refused.'};$cpu0=(Get-Process|Measure-Object CPU -Sum).Sum;$svc0=Get-CimInstance Win32_Service -Filter "Name='HPSysInfoCap'";$p0=if($svc0.ProcessId){Get-Process -Id $svc0.ProcessId -ErrorAction SilentlyContinue};$svcCpu0=if($p0){$p0.CPU}else{$null};$samples=@();$stop=(Get-Date).AddSeconds($SampleSeconds);while((Get-Date)-lt$stop){$samples+=[pscustomobject]@{cpu=[double](Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;disk=[double](Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec};Start-Sleep -Seconds 2};$cpu1=(Get-Process|Measure-Object CPU -Sum).Sum;$svc1=Get-CimInstance Win32_Service -Filter "Name='HPSysInfoCap'";$p1=if($svc1.ProcessId){Get-Process -Id $svc1.ProcessId -ErrorAction SilentlyContinue};$explorer=Get-Process explorer -ErrorAction SilentlyContinue|Sort-Object StartTime|Select-Object -First 1;[ordered]@{schemaVersion=1;experiment='EXP-065';phase=$Phase;run=$Ordinal;bootId=$boot;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');sampleSeconds=$SampleSeconds;desktopProxyMs=if($explorer){($explorer.StartTime.ToUniversalTime()-[datetime]$boot).TotalMilliseconds}else{$null};system=@{processCpuDeltaSeconds=[double]($cpu1-$cpu0);cpuMedian=Median @($samples|ForEach-Object cpu);cpuMAD=Mad @($samples|ForEach-Object cpu);diskMedian=Median @($samples|ForEach-Object disk);diskMAD=Mad @($samples|ForEach-Object disk)};service=@{name=$svc1.Name;startMode=$svc1.StartMode;state=$svc1.State;processId=$svc1.ProcessId;cpuDeltaSeconds=if($p1-and$null-ne$svcCpu0){[double]($p1.CPU-$svcCpu0)}else{$null}};protected=Protected;functional=@{hpSystemInfoDemandStart='needs-evidence';hpSystemInfoWorkflow='needs-evidence';omnissa='needs-evidence';windowsApp='needs-evidence';remoteDesktop='needs-evidence';tailscale='needs-evidence'}}}
function Summarize($d){$runs=@(Get-ChildItem $d -Filter 'run-*.json' -ErrorAction SilentlyContinue|Sort-Object Name|ForEach-Object{Read-Json $_.FullName});$out=[ordered]@{};foreach($phase in 'Baseline','Treatment'){$r=@($runs|Where-Object phase -eq $phase);$out[$phase]=@{runs=$r.Count;desktopProxyMs=@{median=Median @($r|ForEach-Object desktopProxyMs);mad=Mad @($r|ForEach-Object desktopProxyMs)};cpuDeltaSeconds=@{median=Median @($r|ForEach-Object{$_.system.processCpuDeltaSeconds});mad=Mad @($r|ForEach-Object{$_.system.processCpuDeltaSeconds})};diskBytesPerSecond=@{median=Median @($r|ForEach-Object{$_.system.diskMedian});mad=Mad @($r|ForEach-Object{$_.system.diskMedian})}}};$b=$out.Baseline.desktopProxyMs.median;$t=$out.Treatment.desktopProxyMs.median;$pct=if($null-ne$b-and$b-ne0-and$null-ne$t){100*($b-$t)/$b}else{$null};$complete=($out.Baseline.runs-ge$RunsPerArm-and$out.Treatment.runs-ge$RunsPerArm);$class=if(!$complete){'inconclusive'}elseif($null-eq$pct){'inconclusive'}elseif($pct-gt0){'favorable'}elseif([math]::Abs($pct)-lt1){'zero-benefit'}else{'failed'};$s=[ordered]@{schemaVersion=1;experiment='EXP-065';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');groups=$out;improvementPercent=$pct;classification=$class;functionalEvidence='needs-evidence';rawRuns=@($runs|Select-Object phase,run,bootId,capturedUtc);limitations=@('desktopProxyMs uses Explorer start as a readiness proxy','HP System Information demand-start and protected application usability require physical observation')};Write-Json (Paths $d).Summary $s;$s}
function Register-Continuation($d){$exe=(Get-Command powershell.exe).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$p=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $p -Force|Out-Null}
function Unregister-Continuation{Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue}
function Next-Reboot{if($AllowAutomaticReboot){if($PSCmdlet.ShouldProcess($env:COMPUTERNAME,'Restart for next EXP-065 run')){Restart-Computer -Force}}else{'Reboot required; validation resumes at next logon.'}}
Require-Admin;if(!(Test-Path $Provider)){throw 'EXP-065 provider missing.'}
switch($Action){
 'Start'{New-Item -ItemType Directory -Force -Path $EvidenceRoot|Out-Null;if(Test-Path $Pointer){throw 'Active run exists.'};& $Provider -Action Check|Out-Null;if($WhatIfPreference){return};$d=Join-Path $EvidenceRoot ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));New-Item -ItemType Directory -Force -Path $d|Out-Null;Provider Capture $d|Out-Null;Provider DryRun $d|Out-Null;Write-Json (Paths $d).Harness @{phase='Baseline';completed=0;runsPerArm=$RunsPerArm;lastBoot=$null};Write-Json $Pointer @{runDirectory=$d};Register-Continuation $d;Next-Reboot}
 'Continue'{$d=Resolve-Run;$p=Paths $d;$s=Read-Json $p.Harness;$boot=BootId;if($s.lastBoot-eq$boot){throw 'Duplicate boot refused.'};if($s.phase-eq'Treatment'){Provider VerifyReboot $d|Out-Null};$n=[int]$s.completed+1;$r=Collect $s.phase $n $d;Write-Json (Join-Path $d ("run-{0}-{1:D2}.json"-f$s.phase,$n)) $r;$s.completed=$n;$s.lastBoot=$boot;if($s.completed-ge$s.runsPerArm){if($s.phase-eq'Baseline'){Provider Apply $d|Out-Null;Provider Verify $d|Out-Null;$s.phase='Treatment';$s.completed=0}else{Provider Rollback $d|Out-Null;$summary=Summarize $d;Unregister-Continuation;Remove-Item $Pointer -Force;Write-Json $p.Harness $s;return $summary}};Write-Json $p.Harness $s;Next-Reboot}
 'Status'{if(Test-Path $Pointer){Read-Json (Paths (Resolve-Run)).Harness}else{@{active=$false}}}
 'Summarize'{Summarize (Resolve-Run)}
 'Stop'{$d=Resolve-Run;Provider Rollback $d|Out-Null;Unregister-Continuation;Remove-Item $Pointer -Force -ErrorAction SilentlyContinue;@{stopped=$true;runDirectory=$d}}
}
